package com.bananalab.lite;
import java.nio.file.*;import java.util.*;import java.awt.image.*;import javax.imageio.*;import java.io.*;import org.json.*;
public final class Stage60DeepPixelCheck{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static PixelGenerator load(Path r)throws Exception{return new PixelGenerator(Files.newInputStream(r.resolve("assets/pixel-v2/character21.bin")));}
 public static void main(String[] args)throws Exception{Path r=Paths.get(args[0]);PixelGenerator m=load(r);float[] condition=m.conditionFor(0,0xfff8d061,0,0,0);BufferedImage image=ImageIO.read(r.resolve("assets/training/banana-own-target.png").toFile());List<HeadTrainer.Pixel> train=new ArrayList<>(),eval=new ArrayList<>(),replay=new ArrayList<>();for(int y=0;y<16;y++)for(int x=0;x<16;x++){int px=x*8+3,py=y*8+3;HeadTrainer.Pixel row=new HeadTrainer.Pixel(m.coordinates(condition,px,py),NeuralTraining.rgba(image.getRGB(px,py)));if(((x+y)&1)==0)train.add(row);else eval.add(row);}float[] control=m.conditionFor(1,0xff629cdb,0,0,0);for(int y=0;y<8;y++)for(int x=0;x<8;x++){float[] input=m.coordinates(control,x*16+7,y*16+7);replay.add(new HeadTrainer.Pixel(input,m.forward(input)));}
 HeadTrainer.Pixel row=train.get(0);double score=-1;for(HeadTrainer.Pixel candidate:train){float[] pred=m.forward(candidate.x);double total=0;for(int j=0;j<4;j++){double g=(pred[j]-candidate.y[j])*pred[j]*(1-pred[j])*(j==3?1:candidate.y[3]);total+=g*g;}if(total>score){score=total;row=candidate;}}float[][][] base=DeepPixelTrainer.copy(m);DeepPixelTrainer.step(m,row,.02f);for(int l=0;l<4;l++){int ai=0,aj=0;double maximum=0;for(int i=0;i<base[l].length;i++)for(int j=0;j<base[l][i].length;j++){double d=Math.abs(m.weights[l][i][j]-base[l][i][j]);if(d>maximum){maximum=d;ai=i;aj=j;}}check(maximum>0,"nonzero gradient layer "+l);double actual=(base[l][ai][aj]-m.weights[l][ai][aj])/.02;PixelGenerator probe=load(r);float epsilon=.005f;probe.weights[l][ai][aj]+=epsilon;double plus=DeepPixelTrainer.loss(probe,Arrays.asList(row));probe.weights[l][ai][aj]-=2*epsilon;double minus=DeepPixelTrainer.loss(probe,Arrays.asList(row));check(Math.abs(actual-(plus-minus)/(2*epsilon))<.001,"finite difference gradient layer "+l+" "+actual+" vs "+(plus-minus)/(2*epsilon));}
 m=load(r);base=DeepPixelTrainer.copy(m);double before=DeepPixelTrainer.loss(m,eval);DeepPixelTrainer.train(m,train,replay);double after=DeepPixelTrainer.loss(m,eval),drift=DeepPixelTrainer.loss(m,replay);check(after<before-1e-7&&drift<.002,"deep validation and retention "+before+" -> "+after+" drift "+drift);for(int l=0;l<4;l++)check(HeadTrainer.distance(base[l],m.weights[l])>0,"actual changed layer "+l);ByteArrayOutputStream out=new ByteArrayOutputStream();m.save(out);byte[] original=Files.readAllBytes(r.resolve("assets/pixel-v2/character21.bin")),updated=out.toByteArray();check(original.length==updated.length&&!Arrays.equals(original,updated),"compatible real checkpoint");PixelGenerator reopened=new PixelGenerator(new ByteArrayInputStream(updated));check(Math.abs(DeepPixelTrainer.loss(reopened,eval)-after)<1e-9,"reload reproduces loss");Files.write(r.resolve("test/resources/pixel60-deep-candidate.bin"),updated);JSONObject report=new JSONObject().put("before",before).put("after",after).put("retention",drift).put("delta",DeepPixelTrainer.distance(m,base)).put("layers",4);Files.write(r.resolve("test/resources/training60-report.json"),report.toString(2).getBytes("UTF-8"));System.out.println("PASS Stage60 gradients in all4 layers, real backprop, separated-pixel evaluation, replay and saved checkpoint "+report);}
}
